-- O4 STEP datasource
CREATE TABLE IF NOT EXISTS `obs_prometheus_datasource` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL DEFAULT 0,
  `revision` bigint unsigned NOT NULL DEFAULT 1,
  `dept_id` bigint unsigned NULL,
  `name` varchar(128) NOT NULL,
  `type` varchar(32) NOT NULL DEFAULT 'prometheus',
  `url` varchar(512) NOT NULL,
  `access_mode` varchar(32) NOT NULL DEFAULT 'proxy',
  `username` varchar(128) NULL,
  `password` varchar(512) NULL,
  `bearer_token` varchar(1024) NULL,
  `timeout` bigint NULL DEFAULT 30,
  `is_default` tinyint(1) NULL DEFAULT 0,
  `status` varchar(32) NOT NULL DEFAULT 'unknown',
  `last_checked` datetime(3) NULL,
  `created_at` datetime(3) NULL,
  `updated_at` datetime(3) NULL,
  `created_by` varchar(64) NULL,
  `deleted_at` datetime(3) NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_datasource_tenant_name` (`tenant_id`,`name`),
  KEY `idx_datasource_tenant_id` (`tenant_id`,`id`),
  KEY `idx_datasource_tenant_default` (`tenant_id`,`is_default`,`deleted_at`),
  KEY `idx_obs_prometheus_datasource_dept_id` (`dept_id`),
  KEY `idx_obs_prometheus_datasource_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- O4 STEP tenant_id
SET @o4_ddl=IF(NOT EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='obs_prometheus_datasource' AND COLUMN_NAME='tenant_id'),'ALTER TABLE obs_prometheus_datasource ADD COLUMN tenant_id bigint unsigned NOT NULL DEFAULT 0','SELECT 1');
PREPARE o4_stmt FROM @o4_ddl;
EXECUTE o4_stmt;
DEALLOCATE PREPARE o4_stmt;
