SET @o4_ddl=IF(NOT EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='obs_prometheus_datasource' AND COLUMN_NAME='revision'),'ALTER TABLE obs_prometheus_datasource ADD COLUMN revision bigint unsigned NOT NULL DEFAULT 1','SELECT 1');
PREPARE o4_stmt FROM @o4_ddl;
EXECUTE o4_stmt;
DEALLOCATE PREPARE o4_stmt;
