-- O4 STEP obs_query_history
CREATE TABLE IF NOT EXISTS `obs_query_history` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `actor_id` bigint unsigned NOT NULL,
  `datasource_id` bigint unsigned NOT NULL,
  `source_kind` varchar(32) NOT NULL,
  `time_intent` json NOT NULL,
  `row_limit` bigint NOT NULL,
  `result_mode` varchar(16) NOT NULL,
  `outcome` varchar(16) NOT NULL,
  `duration_ms` int unsigned NOT NULL,
  `recipe` json NULL,
  `created_at` datetime(3) NOT NULL,
  `expires_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_history_owner` (`tenant_id`,`actor_id`,`created_at`,`id`),
  KEY `idx_history_source` (`tenant_id`,`datasource_id`),
  KEY `idx_history_expiry` (`expires_at`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- O4 STEP obs_saved_view
CREATE TABLE IF NOT EXISTS `obs_saved_view` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `actor_id` bigint unsigned NOT NULL,
  `datasource_id` bigint unsigned NOT NULL,
  `recipe` json NOT NULL,
  `revision` bigint unsigned NOT NULL DEFAULT 1,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_view_owner` (`tenant_id`,`actor_id`,`updated_at`,`id`),
  KEY `idx_view_source` (`tenant_id`,`datasource_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- O4 STEP obs_query_owner_budget
CREATE TABLE IF NOT EXISTS `obs_query_owner_budget` (
  `tenant_id` bigint unsigned NOT NULL,
  `actor_id` bigint unsigned NOT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`tenant_id`,`actor_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- O4 STEP obs_schema_capability
CREATE TABLE IF NOT EXISTS `obs_schema_capability` (
  `capability` varchar(64) NOT NULL,
  `version` smallint unsigned NOT NULL,
  `created_at` datetime(3) NOT NULL,
  PRIMARY KEY (`capability`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
